#include "cpm_json.h"
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int cpm_alloc(CpmJsonToken *tokens,size_t cap,int *next,CpmJsonType type,int start,int parent){int i=*next;if((size_t)i>=cap)return -1;tokens[i].type=type;tokens[i].start=start;tokens[i].end=-1;tokens[i].size=0;tokens[i].parent=parent;*next=i+1;if(parent>=0)tokens[parent].size++;return i;}
static int cpm_hex(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
int CpmJson_Parse(const char *json,CpmJsonToken *tokens,size_t cap){int pos=0,next=0,parent=-1;if(!json||!tokens||!cap)return -1;while(json[pos]){char c=json[pos];if(isspace((unsigned char)c)||c==':'||c==','){pos++;continue;}if(c=='{'||c=='['){int t=cpm_alloc(tokens,cap,&next,c=='{'?CPM_JSON_OBJECT:CPM_JSON_ARRAY,pos,parent);if(t<0)return -2;parent=t;pos++;continue;}if(c=='}'||c==']'){CpmJsonType want=c=='}'?CPM_JSON_OBJECT:CPM_JSON_ARRAY;if(parent<0||tokens[parent].type!=want)return -3;tokens[parent].end=pos+1;parent=tokens[parent].parent;pos++;continue;}if(c=='"'){int t,start=++pos;t=cpm_alloc(tokens,cap,&next,CPM_JSON_STRING,start,parent);if(t<0)return -2;while(json[pos]&&json[pos]!='"'){if((unsigned char)json[pos]<0x20)return -3;if(json[pos]=='\\'){pos++;if(!json[pos])return -3;if(json[pos]=='u'){int k;for(k=1;k<=4;k++)if(cpm_hex(json[pos+k])<0)return -3;pos+=4;}}pos++;}if(json[pos]!='"')return -3;tokens[t].end=pos;pos++;continue;}else{int t,start=pos;t=cpm_alloc(tokens,cap,&next,CPM_JSON_PRIMITIVE,start,parent);if(t<0)return -2;while(json[pos]&&!isspace((unsigned char)json[pos])&&json[pos]!=','&&json[pos]!=']'&&json[pos]!='}')pos++;tokens[t].end=pos;if(tokens[t].end==start)return -3;continue;}}if(parent!=-1)return -3;return next;}
static int cpm_direct_nth(const CpmJsonToken*t,int count,int parent,int nth){int i,n=0;for(i=parent+1;i<count;i++)if(t[i].parent==parent){if(n==nth)return i;n++;}return -1;}
int CpmJson_ObjectValue(const char *json,const CpmJsonToken*t,int count,int object,const char*key){int direct=0,i;if(!json||!t||!key||object<0||object>=count||t[object].type!=CPM_JSON_OBJECT)return -1;for(i=object+1;i<count;i++){if(t[i].parent!=object)continue;if((direct%2)==0){if(t[i].type==CPM_JSON_STRING&&CpmJson_TokenEquals(json,&t[i],key)){int v=cpm_direct_nth(t,count,object,direct+1);return v;} }direct++;}return -1;}
int CpmJson_ArrayElement(const CpmJsonToken*t,int count,int array,size_t element){if(!t||array<0||array>=count||t[array].type!=CPM_JSON_ARRAY)return -1;return cpm_direct_nth(t,count,array,(int)element);}
int CpmJson_TokenEquals(const char *json,const CpmJsonToken*token,const char*text){size_t n;if(!json||!token||!text||token->start<0||token->end<token->start)return 0;n=(size_t)(token->end-token->start);return strlen(text)==n&&strncmp(json+token->start,text,n)==0;}
static int cpm_utf8(char*out,size_t cap,size_t*used,unsigned cp){if(cp<=0x7F){if(*used+1>=cap)return -2;out[(*used)++]=(char)cp;}else if(cp<=0x7FF){if(*used+2>=cap)return -2;out[(*used)++]=(char)(0xC0|(cp>>6));out[(*used)++]=(char)(0x80|(cp&0x3F));}else{if(*used+3>=cap)return -2;out[(*used)++]=(char)(0xE0|(cp>>12));out[(*used)++]=(char)(0x80|((cp>>6)&0x3F));out[(*used)++]=(char)(0x80|(cp&0x3F));}return 0;}
int CpmJson_GetString(const char *json,const CpmJsonToken*token,char*out,size_t cap){int i;size_t u=0;if(!json||!token||!out||!cap||token->type!=CPM_JSON_STRING)return -1;for(i=token->start;i<token->end;i++){char c=json[i];if(c=='\\'){if(++i>=token->end)return -3;c=json[i];switch(c){case '"':case '\\':case '/':break;case 'b':c='\b';break;case 'f':c='\f';break;case 'n':c='\n';break;case 'r':c='\r';break;case 't':c='\t';break;case 'u':{int k;unsigned cp=0;if(i+4>=token->end)return -3;for(k=0;k<4;k++){int h=cpm_hex(json[++i]);if(h<0)return -3;cp=(cp<<4)|(unsigned)h;}if(cpm_utf8(out,cap,&u,cp)!=0)return -2;continue;}default:return -3;}}if(u+1>=cap)return -2;out[u++]=c;}out[u]='\0';return 0;}
static int cpm_copy_primitive(const char*j,const CpmJsonToken*t,char*b,size_t z){size_t n;if(!j||!t||!b||!z||t->start<0||t->end<t->start)return -1;n=(size_t)(t->end-t->start);if(n+1>z)return -2;memcpy(b,j+t->start,n);b[n]='\0';return 0;}
int CpmJson_GetInt64(const char*j,const CpmJsonToken*t,int64_t*v){char b[64],*e;long long x;if(!v||!t||t->type!=CPM_JSON_PRIMITIVE)return -1;if(cpm_copy_primitive(j,t,b,sizeof(b))!=0)return -2;x=strtoll(b,&e,10);if(*e)return -3;*v=(int64_t)x;return 0;}
int CpmJson_GetDouble(const char*j,const CpmJsonToken*t,double*v){char b[96],*e;double x;if(!v||!t||t->type!=CPM_JSON_PRIMITIVE)return -1;if(cpm_copy_primitive(j,t,b,sizeof(b))!=0)return -2;x=strtod(b,&e);if(*e)return -3;*v=x;return 0;}
int CpmJson_GetBool(const char*j,const CpmJsonToken*t,int*v){if(!v||!t||t->type!=CPM_JSON_PRIMITIVE)return -1;if(CpmJson_TokenEquals(j,t,"true")){*v=1;return 0;}if(CpmJson_TokenEquals(j,t,"false")){*v=0;return 0;}return -3;}
static int wput(CpmJsonWriter*w,const char*s,size_t n){if(!w||w->error)return -1;if(w->length+n+1>w->capacity){w->error=-2;return -2;}memcpy(w->buffer+w->length,s,n);w->length+=n;w->buffer[w->length]='\0';return 0;}
static int wvalue(CpmJsonWriter*w){if(w->depth<=0)return w->length==0?0:-3;{int d=w->depth-1;if(w->container[d]=='a'){if(w->count[d]++>0)return wput(w,",",1);return 0;}if(!w->expectingValue[d])return -3;w->expectingValue[d]=0;w->count[d]++;return 0;}}
static int wescaped(CpmJsonWriter*w,const char*s){const unsigned char*p=(const unsigned char*)s;if(wput(w,"\"",1)!=0)return -2;while(*p){char esc[7];switch(*p){case '"':if(wput(w,"\\\"",2))return -2;break;case '\\':if(wput(w,"\\\\",2))return -2;break;case '\b':if(wput(w,"\\b",2))return -2;break;case '\f':if(wput(w,"\\f",2))return -2;break;case '\n':if(wput(w,"\\n",2))return -2;break;case '\r':if(wput(w,"\\r",2))return -2;break;case '\t':if(wput(w,"\\t",2))return -2;break;default:if(*p<0x20){snprintf(esc,sizeof(esc),"\\u%04X",(unsigned)*p);if(wput(w,esc,6))return -2;}else if(wput(w,(const char*)p,1))return -2;}p++;}return wput(w,"\"",1);}
void CpmJsonWriter_Init(CpmJsonWriter*w,char*b,size_t c){if(w){memset(w,0,sizeof(*w));w->buffer=b;w->capacity=c;if(b&&c)b[0]='\0';else w->error=-1;}}
static int wbegin(CpmJsonWriter*w,char c){if(wvalue(w)!=0)return w->error?w->error:-3;if(w->depth>=32)return -4;if(wput(w,c=='o'?"{":"[",1)!=0)return -2;w->container[w->depth]=c;w->count[w->depth]=0;w->expectingValue[w->depth]=0;w->depth++;return 0;}
int CpmJsonWriter_BeginObject(CpmJsonWriter*w){return wbegin(w,'o');}int CpmJsonWriter_BeginArray(CpmJsonWriter*w){return wbegin(w,'a');}
static int wend(CpmJsonWriter*w,char c){if(!w||w->depth<=0||w->container[w->depth-1]!=c||w->expectingValue[w->depth-1])return -3;w->depth--;return wput(w,c=='o'?"}":"]",1);}
int CpmJsonWriter_EndObject(CpmJsonWriter*w){return wend(w,'o');}int CpmJsonWriter_EndArray(CpmJsonWriter*w){return wend(w,'a');}
int CpmJsonWriter_Key(CpmJsonWriter*w,const char*key){int d;if(!w||!key||w->depth<=0)return -1;d=w->depth-1;if(w->container[d]!='o'||w->expectingValue[d])return -3;if(w->count[d]>0&&wput(w,",",1)!=0)return -2;if(wescaped(w,key)!=0||wput(w,":",1)!=0)return -2;w->expectingValue[d]=1;return 0;}
int CpmJsonWriter_String(CpmJsonWriter*w,const char*v){if(!v)return CpmJsonWriter_Null(w);if(wvalue(w)!=0)return -3;return wescaped(w,v);}
int CpmJsonWriter_Int64(CpmJsonWriter*w,int64_t v){char b[64];int n;if(wvalue(w)!=0)return -3;n=snprintf(b,sizeof(b),"%lld",(long long)v);return n>0?wput(w,b,(size_t)n):-3;}
int CpmJsonWriter_Double(CpmJsonWriter*w,double v){char b[64];int n;if(wvalue(w)!=0)return -3;n=snprintf(b,sizeof(b),"%.17g",v);return n>0?wput(w,b,(size_t)n):-3;}
int CpmJsonWriter_Bool(CpmJsonWriter*w,int v){if(wvalue(w)!=0)return -3;return wput(w,v?"true":"false",v?4:5);}int CpmJsonWriter_Null(CpmJsonWriter*w){if(wvalue(w)!=0)return -3;return wput(w,"null",4);}const char*CpmJsonWriter_Data(const CpmJsonWriter*w){return w&&w->buffer?w->buffer:"";}
